/* Spacer pushes the first panel to start at the snap position */
.content-spacer {
  flex: 0 0 var(--snap-offset);
  height: 100%;
  pointer-events: none;
}

.panel {
  flex: 0 0 calc(100vw - var(--snap-offset));
  width: calc(100vw - var(--snap-offset));
  height: 100vh;
  overflow-y: auto;
  overflow-x: hidden;
  scroll-snap-align: start;
  scroll-snap-stop: always;
  /* Default padding: text content clears the navbar overlap area */
  padding: 72px 56px 80px calc(var(--bleed) + 32px);
  scrollbar-width: none;
  -ms-overflow-style: none;
}
.panel::-webkit-scrollbar { display: none; }

.panel-inner {
  max-width: 820px;
  margin: 0 auto;
}

/* Sections that bleed left into the navbar area (hero, artwork) */
.bleed-left {
  margin-left: calc(-1 * (var(--bleed) + 32px));
  width: calc(100% + var(--bleed) + 32px);
}

