input.old_string:
/* Project artwork */
.artwork {
  width: 100%;
  aspect-ratio: 16 / 8;
  border-radius: 16px;
  margin: 12px 0 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 36px;
  font-weight: 700;
  letter-spacing: -0.01em;
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.08);
  position: relative;
  overflow: hidden;
}
.artwork::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 30% 25%, rgba(255,255,255,0.32), transparent 55%);
}
.artwork span { position: relative; z-index: 1; }

input.new_string:
/* Project hero/artwork */
.artwork {
  aspect-ratio: 16 / 7;
  border-radius: 0 22px 22px 0;
  margin: 14px 0 36px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 36px;
  font-weight: 700;
  letter-spacing: -0.01em;
  box-shadow: 0 14px 40px rgba(0, 0, 0, 0.08);
  position: relative;
  overflow: hidden;
}
.artwork::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 30% 25%, rgba(255,255,255,0.32), transparent 55%);
}
.artwork span { position: relative; z-index: 1; padding-left: var(--bleed); }

/* Image placeholders */
.image-placeholder {
  background: linear-gradient(135deg, #f4f4f6, #e9eaf0);
  border: 1px dashed rgba(0, 0, 0, 0.12);
  border-radius: 14px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 6px;
  color: var(--text-tertiary);
  font-size: 12px;
  text-align: center;
  padding: 24px;
  aspect-ratio: 16 / 9;
  margin: 14px 0;
}
.image-placeholder .ph-icon {
  width: 28px; height: 28px;
  opacity: 0.5;
}
.image-placeholder .ph-label {
  font-weight: 500;
  color: var(--text-secondary);
  font-size: 13px;
}
.image-placeholder .ph-hint {
  font-size: 11px;
  color: var(--text-tertiary);
  max-width: 320px;
  line-height: 1.4;
}
.image-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
  margin: 14px 0;
}
.image-row .image-placeholder { margin: 0; aspect-ratio: 4 / 3; }
.image-placeholder.tall { aspect-ratio: 4 / 5; }
.image-placeholder.wide { aspect-ratio: 21 / 9; }

/* Process / outcomes lists */
.pill-list {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin: 4px 0 22px;
}
.pill {
  display: inline-flex;
  align-items: center;
  padding: 4px 10px;
  font-size: 12px;
  font-weight: 500;
  color: var(--text-secondary);
  background: rgba(0, 0, 0, 0.04);
  border-radius: 999px;
}

.outcome-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  margin: 14px 0 22px;
}
.outcome-card {
  background: rgba(0, 0, 0, 0.025);
  border-radius: 12px;
  padding: 16px 18px;
}
.outcome-card .n {
  font-size: 24px;
  font-weight: 700;
  letter-spacing: -0.01em;
}
.outcome-card .l {
  font-size: 12px;
  color: var(--text-secondary);
  margin-top: 4px;
  line-height: 1.4;
}

