.bottom-nav {
  display: none;
  position: fixed;
  left: 16px;
  right: 16px;
  bottom: 16px;
  height: 60px;
  background: rgba(245, 245, 247, 0.78);
  backdrop-filter: saturate(180%) blur(30px);
  -webkit-backdrop-filter: saturate(180%) blur(30px);
  border-radius: 22px;
  box-shadow: 0 12px 36px rgba(0, 0, 0, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.6);
  padding: 6px;
  z-index: 50;
  gap: 6px;
  align-items: stretch;
}
.bn-tab {
  flex: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  border: none;
  background: transparent;
  border-radius: 16px;
  color: var(--text-secondary);
  font-family: inherit;
  font-size: 14px;
  font-weight: 500;
  cursor: pointer;
  transition: background 0.2s, color 0.2s;
}
.bn-tab svg { width: 18px; height: 18px; }
.bn-tab.active {
  background: white;
  color: var(--accent);
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06);
}

/* ===== Projects list (deep dive entry on mobile) ===== */
.panel[data-id="projects-list"] {
  display: none;
}
.projects-list-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 22px;
}
.pl-card {
  text-align: left;
  background: white;
  border: 1px solid var(--divider);
  border-radius: 16px;
  padding: 14px;
  cursor: pointer;
  transition: transform 0.18s, box-shadow 0.18s, border-color 0.18s;
  font-family: inherit;
  color: inherit;
}
.pl-card:hover, .pl-card:focus-visible {
  transform: translateY(-2px);
  box-shadow: 0 10px 22px rgba(0, 0, 0, 0.06);
  border-color: rgba(0, 122, 255, 0.25);
  outline: none;
}
.pl-card .pl-thumb {
  width: 100%;
  aspect-ratio: 16 / 10;
  border-radius: 10px;
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-weight: 700;
  letter-spacing: -0.01em;
  font-size: 14px;
  position: relative;
  overflow: hidden;
}
.pl-card .pl-thumb::after {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 28% 28%, rgba(255,255,255,0.32), transparent 55%);
}
.pl-card .pl-thumb span { position: relative; z-index: 1; }
.pl-card .pl-title { font-size: 14px; font-weight: 600; margin-bottom: 2px; }
.pl-card .pl-tag { font-size: 12px; color: var(--text-tertiary); }
.pl-card .pl-arrow {
  margin-top: 10px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  color: var(--accent);
  font-size: 12px;
  font-weight: 500;
}

@media (max-width: 1100px) {
  .welcome h1 { font-size: 48px; }
  .process-flow { grid-template-columns: repeat(2, 1fr); }
  .process-flow::before { display: none; }
  .focus-grid { grid-template-columns: 1fr; }
  .contact-grid { grid-template-columns: 1fr; }
  .mini-process { grid-template-columns: repeat(2, 1fr); }
  .impact-bar { grid-template-columns: 110px 1fr 60px; }
}

@media (max-width: 768px) {
  :root {
    --sidebar-width: 0px;
    --sidebar-gap: 0px;
    --bleed: 0px;
    --content-offset: 0px;
    --snap-offset: 0px;
  }
  .sidebar { display: none; }
  .bottom-nav { display: flex; }
  .panel {
    padding: 28px 20px 110px 20px;
    width: 100vw;
    flex: 0 0 100vw;
  }
